import * as THREE from './assets/three.module.js';
export async function initModel(){const host=document.getElementById('model-view');const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(host.clientWidth,host.clientHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.4;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(38,host.clientWidth/host.clientHeight,.1,1000);camera.position.set(115,78,125);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight(0xe6f2ff,0x668798,3));const light=new THREE.DirectionalLight(0xffffff,4);light.position.set(30,70,40);scene.add(light);const fill=new THREE.DirectionalLight(0x768cff,2);fill.position.set(-60,20,-40);scene.add(fill);const group=new THREE.Group();scene.add(group);
const [meta,buffer]=await Promise.all([fetch('./assets/drone-model.json').then(r=>{if(!r.ok)throw Error('Model metadata unavailable');return r.json()}),fetch('./assets/drone.bin').then(r=>{if(!r.ok)throw Error('Model unavailable');return r.arrayBuffer()})]);const colors={0:0xd2dde2,1:0x79dcca,2:0x8edfdb,3:0x4358ed,4:0x252a32,8:0x151922,9:0x141a22,10:0xa2d86b,11:0x354152,12:0x253144};for(const part of meta){const geom=new THREE.BufferGeometry();let offset=part.offset;geom.setAttribute('position',new THREE.BufferAttribute(new Float32Array(buffer,offset,part.vertices*3),3));offset+=part.vertices*12;geom.setAttribute('normal',new THREE.BufferAttribute(new Float32Array(buffer,offset,part.vertices*3),3));offset+=part.vertices*12;geom.setIndex(new THREE.BufferAttribute(new Uint32Array(buffer,offset,part.indices),1));const mat=new THREE.MeshStandardMaterial({color:colors[part.layer]??0xc5d8e8,metalness:part.layer===0?.6:.25,roughness:.35,side:THREE.DoubleSide});group.add(new THREE.Mesh(geom,mat))}const box=new THREE.Box3().setFromObject(group),center=box.getCenter(new THREE.Vector3());group.children.forEach(c=>c.position.sub(center));group.rotation.y=-.35;host.appendChild(renderer.domElement);host.querySelector('.model-poster').hidden=true;host.querySelector('.model-controls').hidden=false;host.querySelector('.model-loading').textContent='';
let yaw=-.35,pitch=0,down=false,lastX=0,lastY=0,auto=false,visible=true,lastTime=0;const fine=matchMedia('(pointer:fine)').matches;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
renderer.domElement.addEventListener('pointerdown',e=>{down=true;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointerup',()=>down=false);renderer.domElement.addEventListener('pointercancel',()=>down=false);renderer.domElement.addEventListener('pointermove',e=>{if(down){yaw+=(e.clientX-lastX)*.008;pitch=Math.max(-.8,Math.min(.8,pitch+(e.clientY-lastY)*.005));lastX=e.clientX;lastY=e.clientY}else if(fine&&!auto&&!reduced){const r=host.getBoundingClientRect();yaw=-.35+(e.clientX-r.left-r.width/2)/r.width*.8;pitch=(e.clientY-r.top-r.height/2)/r.height*.3}});renderer.domElement.addEventListener('pointerleave',()=>{if(!down&&!auto){yaw=-.35;pitch=0}});document.getElementById('reset-model').onclick=()=>{yaw=-.35;pitch=0;auto=false;document.getElementById('rotate-model').setAttribute('aria-pressed','false')};document.getElementById('rotate-model').onclick=e=>{auto=!auto;e.currentTarget.setAttribute('aria-pressed',String(auto))};
const ro=new ResizeObserver(()=>{camera.aspect=host.clientWidth/host.clientHeight;camera.position.set(host.clientWidth<600?155:115,host.clientWidth<600?105:78,host.clientWidth<600?175:125);camera.lookAt(0,0,0);camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight)});ro.observe(host);new IntersectionObserver(entries=>visible=entries[0].isIntersecting).observe(host);function animate(time){requestAnimationFrame(animate);if(!visible||document.hidden){lastTime=time;return}const dt=Math.min((time-lastTime)/1000,.05);lastTime=time;if(auto)yaw+=dt*.3;group.rotation.y+=(yaw-group.rotation.y)*.12;group.rotation.x+=(pitch-group.rotation.x)*.12;renderer.render(scene,camera)}requestAnimationFrame(animate);}
